// Aircraft Carrier: The largest ship, taking up five spaces on the board.
// Battleship: The second-largest ship, covering four spaces.
// Cruiser: A three-space ship.
// Submarine: Another three-space ship.
// Destroyer: The smallest ship in the game, occupying two spaces.

class Ship {
  constructor(shipName, initialShipPlacementCell, shipOrientation) {
    this.shipName = shipName;
    switch (shipName) {
      case "aircraftCarrier":
        this.shipLength = 5;
        break;
      case "battleship":
        this.shipLength = 4;
        break;
      case "cruiser":
      case "submarine":
        this.shipLength = 3;
        break;
      case "destroyer":
        this.shipLength = 2;
        break;
    }

    this.timesHit = 0;
    this.initialShipPlacementCell = initialShipPlacementCell;
    this.shipOrientation = shipOrientation;
    this.activeShipCoordinates = [];
  }

  hitShip() {
    this.timesHit = this.timesHit + 1;
  }

  isSunk() {
    if (this.shipLength === this.timesHit) {
      return true;
    } else {
      return false;
    }
  }

  getInitialShipPlacementCell() {
    return this.initialShipPlacementCell;
  }

  addToActiveShipCoordinates(shipCoordinate) {
    this.activeShipCoordinates.push(shipCoordinate);
    console.log("activeShipCoordinates", this.activeShipCoordinates);
  }

  getActiveShipCoordinates() {
    return this.activeShipCoordinates;
  }
}

export default Ship;

